files.before/src/Domain.java:
record User(String tenant) {}
record Document(String id, String tenant, String payload) {}
interface Documents { Document load(String id); }
interface Store { String read(User user, String id); }
class Forbidden extends RuntimeException {}

files.before/src/RawStore.java:
final class RawStore implements Store {
 private final Documents documents;
 RawStore(Documents documents) { this.documents = documents; }
 public String read(User user, String id) { return documents.load(id).payload(); }
}

files.before/src/CheckedStore.java:
final class CheckedStore implements Store {
 private final Documents documents;
 CheckedStore(Documents documents) { this.documents = documents; }
 public String read(User user, String id) {
  Document document = documents.load(id);
  if (!document.tenant().equals(user.tenant())) throw new Forbidden();
  return document.payload();
 }
}

files.before/src/Authorizer.java:
final class Authorizer {
 private final Documents documents;
 Authorizer(Documents documents) { this.documents = documents; }
 void requireAccess(User user, String id) {
  if (!documents.load(id).tenant().equals(user.tenant())) throw new Forbidden();
 }
}

files.before/src/ExportService.java:
final class ExportService {
 private final Authorizer authorizer;
 private final Store store;
 ExportService(Authorizer authorizer, Store store) { this.authorizer = authorizer; this.store = store; }
 String export(User user, String id) {
  authorizer.requireAccess(user, id);
  return store.read(user, id);
 }
}

files.before/src/Components.java:
final class Components {
 private final Documents documents;
 Components(Documents documents) { this.documents = documents; }
 ExportService interactive() { return new ExportService(new Authorizer(documents), new CheckedStore(documents)); }
 ExportService scheduled() { return new ExportService(new Authorizer(documents), new RawStore(documents)); }
}

files.before/src/InteractiveDownload.java:
final class InteractiveDownload {
 private final Components components;
 InteractiveDownload(Components components) { this.components = components; }
 String download(User user, String id) { return components.interactive().export(user, id); }
}

files.before/src/ScheduledExportJob.java:
import java.util.List;
final class ScheduledExportJob {
 private final Components components;
 ScheduledExportJob(Components components) { this.components = components; }
 List<String> run(User user, List<String> ids) { return ids.stream().map(id -> components.scheduled().export(user, id)).toList(); }
}

