import test from 'node:test';
import assert from 'node:assert/strict';
import {save,load} from '../src/saved-filters.mjs';
const memory=()=>{const values=new Map();return {put:(t,n,v)=>values.set(JSON.stringify([t,n]),v),get:(t,n)=>values.get(JSON.stringify([t,n]))};};
test('save and retrieve',()=>{const s=memory();save(s,'a','recent','age<7');assert.equal(load(s,'a','recent'),'age<7');});
